#!/usr/bin/env bash
#
# vendor-sqlcipher.sh — generate the SQLCipher amalgamation this repo builds
# against, into internal/signal/ (gitignored).
#
# Reading Signal Desktop's database needs SQLCipher, and SQLCipher only ships as
# source: the single-file "amalgamation" (sqlite3.c) is generated by its build,
# not published as a release artifact. Rather than commit ~10 MB of third-party C,
# we generate it here — pinned to a tag and verified by SHA-256, so every build
# gets byte-identical sources.
#
# Takes ~10s. Needs curl and a C compiler; SQLCipher's own bundled jimsh handles
# the TCL codegen, so no system tclsh is required.
#
# Usage:
#   bin/vendor-sqlcipher.sh          # no-op if the sources are already current
#   bin/vendor-sqlcipher.sh --force  # regenerate regardless

set -euo pipefail

VERSION="4.9.0"
TARBALL_SHA256="91936630ce58a9979de3136bd5292535ee0c0b2d8e901c483335ac4fb2be4185"

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DEST="$REPO_ROOT/internal/signal"
STAMP="$DEST/.sqlcipher-version"

die() { echo "vendor-sqlcipher: $*" >&2; exit 1; }

force=false
[[ "${1:-}" == "--force" ]] && force=true

# Already vendored at this version? Nothing to do — keeps `make build` fast.
if ! $force && [[ -f "$DEST/sqlite3.c" && -f "$DEST/sqlite3.h" && -f "$DEST/sqlite3ext.h" ]] \
   && [[ "$(cat "$STAMP" 2>/dev/null || true)" == "$VERSION" ]]; then
  echo "SQLCipher $VERSION already vendored."
  exit 0
fi

command -v curl >/dev/null 2>&1 || die "curl not found"
command -v cc   >/dev/null 2>&1 || die "no C compiler found (install Xcode command line tools)"

tmp="$(mktemp -d "${TMPDIR:-/tmp}/sqlcipher-vendor.XXXXXX")"
trap 'rm -rf "$tmp"' EXIT

url="https://github.com/sqlcipher/sqlcipher/archive/refs/tags/v${VERSION}.tar.gz"
echo "Downloading SQLCipher ${VERSION}..."
curl -fsSL -o "$tmp/src.tar.gz" "$url" || die "download failed: $url"

# Verify before we run any of it — this is third-party code we're about to
# compile into the binary that reads your messages.
actual="$(shasum -a 256 "$tmp/src.tar.gz" | awk '{print $1}')"
[[ "$actual" == "$TARBALL_SHA256" ]] \
  || die "checksum mismatch for v${VERSION}
  expected $TARBALL_SHA256
  actual   $actual"

tar xzf "$tmp/src.tar.gz" -C "$tmp"
src="$tmp/sqlcipher-${VERSION}"

echo "Building the amalgamation (~10s)..."
# --disable-tcl skips the TCL *bindings*; the amalgamation codegen still runs,
# via the jimsh interpreter SQLCipher builds from its own tree.
( cd "$src" && ./configure --disable-tcl >/dev/null 2>&1 && make sqlite3.c >/dev/null 2>&1 ) \
  || die "amalgamation build failed (re-run by hand in $src to see why)"

for f in sqlite3.c sqlite3.h sqlite3ext.h; do
  [[ -f "$src/$f" ]] || die "expected $f but the build did not produce it"
  cp "$src/$f" "$DEST/$f"
done
echo "$VERSION" > "$STAMP"

echo "Vendored SQLCipher $VERSION -> internal/signal/ (gitignored)"
